import{_ as a,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Widget and tool package packer","description":"Validate and create .wg and .tp packages for HA Grafik Visual Studio.","frontmatter":{"title":"Widget and tool package packer","description":"Validate and create .wg and .tp packages for HA Grafik Visual Studio."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/packer.md","filePath":"en/projects/grafik-visual-studio/packer.md","lastUpdated":1793123188000}'),s={name:"en/projects/grafik-visual-studio/packer.md"};function n(o,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="widget-and-tool-package-packer" tabindex="-1">Widget and tool package packer <a class="header-anchor" href="#widget-and-tool-package-packer" aria-label="Permalink to &quot;Widget and tool package packer&quot;">​</a></h1><p>Packages and helper tools are provided centrally at <a href="https://visualstudio.ugso-software.de/?lang=en" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a>. This open-source page provides descriptions and instructions; downloads are provided by the package catalog.</p><p>The packer creates a widget package (<code>.wg</code>) or tool package (<code>.tp</code>) for HA Grafik Visual Studio from a source folder. Both files are ZIP archives with a dedicated extension. Before export, the packer validates the manifest, package structure, referenced SVG/PNG images and limits of the <a href="./widget-packages">widget package interface</a> or <a href="./tool-packages">tool package interface</a>. Packages for the current 0.1 interfaces contain no executable code.</p><h2 id="create-a-package" tabindex="-1">Create a package <a class="header-anchor" href="#create-a-package" aria-label="Permalink to &quot;Create a package&quot;">​</a></h2><ol><li>Put <code>manifest.json</code> at the root of a source folder. Referenced images belong under <code>icons/</code>. The two interface pages show the required fields and examples.</li><li>Select <strong>Widget package</strong> or <strong>Tool package</strong> in the packer, then choose the source folder and an existing export folder.</li><li>Review the validation list, package ID, version, license and target name. <strong>Export</strong> becomes available only for a valid package and unused target name. Existing files are not overwritten.</li><li>Install the resulting <code>.wg</code> or <code>.tp</code> file in Studio under <strong>Settings → Widget packages</strong> or <strong>Settings → Tools</strong>. The older <code>.wg.zip</code> and <code>.tp.zip</code> extensions remain supported.</li></ol><p>The packer uses the same validation rules as its bundled Studio importer. Packer 0.3.0 supports up to 64 widgets per package; a tool package contains exactly one tool in interface 0.1. Studio also validates every imported package independently.</p><h2 id="github-and-direct-registration" tabindex="-1">GitHub and direct registration <a class="header-anchor" href="#github-and-direct-registration" aria-label="Permalink to &quot;GitHub and direct registration&quot;">​</a></h2><p>Starting with test version <strong>0.3.1</strong>, an existing package with identical file contents appears in green as <strong>Datei gespeichert</strong> (file saved), including after restarting the packer. Export remains disabled. Different contents still trigger the overwrite protection. The wide <strong>GitHub &amp; Katalog …</strong> button is directly below the checklist.</p><p>Since <strong>Packer 0.3.0</strong>, <strong>GitHub &amp; Katalog …</strong> opens an exported <code>.wg</code> or <code>.tp</code> package for validation and publishing. Test version <strong>0.3.1</strong>, available below, includes this feature and the corrected saved-file status.</p><ol><li>Install the <a href="https://cli.github.com/" target="_blank" rel="noreferrer">GitHub CLI</a> and sign in from a terminal with <code>gh auth login</code>. Enter your public repository and choose <strong>Releases laden</strong> (load releases).</li><li>Select a release tag and confirm <strong>Paket auf GitHub veröffentlichen</strong> (publish package on GitHub). To create a release, enable <strong>Release für vorhandenen Git-Tag erstellen</strong>; the Git tag must already exist on GitHub. Existing assets are never overwritten.</li><li>The download link is filled automatically. Alternatively, enter an existing HTTPS download link for a fixed <code>.wg</code> or <code>.tp</code> version and skip GitHub publishing.</li><li>Complete the license link, description, internal contact email and minimum Studio version. Choose <strong>Nein / Ja / Unsicher</strong> (No / Yes / Unsure) for new Studio features. Yes or Unsure requires a description and allows an unknown minimum version.</li><li>Read the <a href="https://visualstudio.ugso-software.de/privacy?lang=en" target="_blank" rel="noreferrer">registration notice</a>, confirm processing and distribution rights, then choose <strong>Im Katalog registrieren</strong> (register in catalog). Review the recipient and details before sending. The original package is uploaded for automatic analysis.</li><li>Copy the private management link after a successful submission. The package appears in the catalog after manual review and approval. If the network result is uncertain, check whether the version was saved first; the packer never retries automatically.</li></ol><p>The contact email goes internally to the catalog and optionally its configured review mailbox. Names, email and website are not published. The packer remembers only the repository and license link, never contact emails, GitHub tokens, consents or management links. Network tasks run in the background. Widget source folders may also contain <code>LICENSE.txt</code> and <code>README.md</code>.</p><h2 id="application-and-file-types" tabindex="-1">Application and file types <a class="header-anchor" href="#application-and-file-types" aria-label="Permalink to &quot;Application and file types&quot;">​</a></h2><p>The Qt interface runs on Windows and Linux. <strong>Register extensions</strong> first previews the changes and, after confirmation, adds dedicated icons and Open With entries for <code>.wg</code> and <code>.tp</code> for the current user. It does not change an existing default application. The packer can inspect an existing package without installing it. Repeat file-type registration after moving the application.</p><p>Version <strong>0.3.1</strong> is available as a signed test release for Windows and Linux in the <a href="https://visualstudio.ugso-software.de/?kind=helper&amp;lang=en" target="_blank" rel="noreferrer">package catalog</a>:</p><table tabindex="0"><thead><tr><th>System</th><th>Download</th><th>SHA-256</th></tr></thead><tbody><tr><td>Windows x86_64</td><td><a href="https://visualstudio.ugso-software.de/downloads/helpertools/HA-Grafik-Packer-0.3.1-windows-x86_64.zip" target="_blank" rel="noreferrer">Download ZIP</a></td><td><code>7047e6ee5bb2327cf80432d2c37e0f82516284c22c0d4910ff3d4d64950efd8a</code></td></tr><tr><td>Linux x86_64</td><td><a href="https://visualstudio.ugso-software.de/downloads/helpertools/HA-Grafik-Packer-0.3.1-linux-x86_64.tar.gz" target="_blank" rel="noreferrer">Download TAR.GZ</a></td><td><code>e094331c7281957764dee38a8a117d932a2589581117daf68f1e146b71fd9a19</code></td></tr></tbody></table><p>Extract the entire archive and run <code>HA-Grafik-Packer.exe</code> or <code>HA-Grafik-Packer</code>. Keep the <code>_internal</code> folder beside it; the Qt libraries there can be replaced separately. Both platform builds passed tests and a self-test after extraction. Linux needs system Qt libraries for EGL/OpenGL. License texts and notices are included in the archive.</p><h2 id="verify-a-download" tabindex="-1">Verify a download <a class="header-anchor" href="#verify-a-download" aria-label="Permalink to &quot;Verify a download&quot;">​</a></h2><p>For version 0.3.1, download <a href="https://visualstudio.ugso-software.de/downloads/helpertools/SHA256SUMS-0.3.1" target="_blank" rel="noreferrer">SHA256SUMS-0.3.1</a> and <a href="https://visualstudio.ugso-software.de/downloads/helpertools/SHA256SUMS-0.3.1.sig" target="_blank" rel="noreferrer">SHA256SUMS-0.3.1.sig</a>. The <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-opensource-docs/main/docs/public/keys/packer-allowed-signers" target="_blank" rel="noreferrer">OpenSSH allowed-signers file</a> and <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/packer-release.pub" target="_blank" rel="noreferrer">public release key</a> are distributed separately. The Ed25519 fingerprint is <code>SHA256:W3iUvKedcI4FWS1kMoBrLlrAF2GbsB4sELphG0uITLE</code>. The earlier checksum files without a version number belong to 0.2.0.</p><p>On Linux, verify the signature first, then the hashes in the download directory:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packer-allowed-signers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packer-release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ha-grafik-visual-studio-packer-release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1.sig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>On Windows, use the same signature parameters in <code>cmd.exe</code> with the shown input redirection. Then compare <code>certutil -hashfile FILENAME SHA256</code> with the value in <code>SHA256SUMS-0.3.1</code>. Obtain the key and allowed-signers file from the linked sources before verifying. The Packer source remains in a private development repository.</p>`,21)])])}const u=a(s,[["render",n]]);export{g as __pageData,u as default};
